211	export function buildChunkMesh(gl: WebGL2RenderingContext, world: World, rocks: BlockRegistry, cx: number, cz: number): ChunkMesh {
212	  const chunk = world.chunkAt(cx, cz);
213	  if (!chunk) return { solid: null, translucent: null };
214	  const solid = new Builder();
215	  const trans = new Builder();
216	  const baseX = cx * 16, baseZ = cz * 16;
217	
218	  for (let y = WORLD_MIN_Y; y < WORLD_MAX_Y; y++) {
219	    for (let lz = 0; lz < 16; lz++) {
220	      for (let lx = 0; lx < 16; lx++) {
221	        const x = baseX + lx, z = baseZ + lz;
222	        const id = chunk.blocks[world.idx(x, y, z)];
223	        if (id === 0) continue;
224	        const def = rocks.get(id);
225	        if (!def.flags) continue;
226	        const target = rocks.translucent[id] ? trans : solid;
227	        if (def.custom) {
228	          emitFluid(target, world, rocks, x, y, z, id, def);
229	          continue;
230	        }
231	        for (const q of def.quads) {
232	          if (isCulled(world, rocks, x, y, z, id, q)) continue;
233	          const tint = tintFor(world, def, q.ti, x, z);
234	          const positions = [q.p[0], q.p[1], q.p[2], q.p[3], q.p[4], q.p[5], q.p[6], q.p[7], q.p[8], q.p[9], q.p[10], q.p[11]];
235	          const aoEnabled = q.ao && !def.flags.noAO;
236	          const shade = def.flags.emissive ? 1 : q.shade ? FACE_SHADE[q.d] : 1;
237	          addStructuredQuad(target, world, rocks, def, x, y, z, q.d, positions, q.uv, q.layer, q.anim,
238	            tint, shade, aoEnabled, def.flags.emissive);
239	        }
240	      }
241	    }
242	  }
243	
244	  const make = (b: Builder): MeshGroup | null => {
245	    if (b.indexCount === 0) return null;
246	    const vbo = gl.createBuffer()!;
247	    gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
248	    gl.bufferData(gl.ARRAY_BUFFER, b.data.subarray(0, b.len), gl.STATIC_DRAW);
249	    const ibo = gl.createBuffer()!;
250	    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
251	    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, b.indices.subarray(0, b.indexCount), gl.STATIC_DRAW);
252	    const vao = gl.createVertexArray()!;
253	    gl.bindVertexArray(vao);
254	    gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
255	    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, STRIDE * 4, 0);
256	    gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, STRIDE * 4, 12);
257	    gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 1, gl.FLOAT, false, STRIDE * 4, 20);
258	    gl.enableVertexAttribArray(3); gl.vertexAttribPointer(3, 1, gl.FLOAT, false, STRIDE * 4, 24);
259	    gl.enableVertexAttribArray(4); gl.vertexAttribPointer(4, 2, gl.FLOAT, false, STRIDE * 4, 28);
260	    gl.enableVertexAttribArray(5); gl.vertexAttribPointer(5, 1, gl.FLOAT, false, STRIDE * 4, 36);
261	    gl.enableVertexAttribArray(6); gl.vertexAttribPointer(6, 3, gl.FLOAT, false, STRIDE * 4, 40);
262	    gl.enableVertexAttribArray(7); gl.vertexAttribPointer(7, 1, gl.FLOAT, false, STRIDE * 4, 52);
263	    gl.enableVertexAttribArray(8); gl.vertexAttribPointer(8, 3, gl.FLOAT, false, STRIDE * 4, 56);
264	    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
265	    gl.bindVertexArray(null);
266	    return { vao, vbo, ibo, count: b.indexCount, verts: b.len / STRIDE };
267	  };
268	
269	  return { solid: make(solid), translucent: make(trans) };
270	}
271	
272	export function disposeMesh(gl: WebGL2RenderingContext, mesh: ChunkMesh | null): void {
273	  if (!mesh) return;
274	  for (const g of [mesh.solid, mesh.translucent]) {
275	    if (!g) continue;
276	    gl.deleteVertexArray(g.vao);
277	    gl.deleteBuffer(g.vbo);
278	    gl.deleteBuffer(g.ibo);
279	  }
280	}
