333	      const rough = (fbm2(x * 0.055, z * 0.055, 2, this.seed + 91) - 0.5) * 4.6;
334	      depth += bankNoise * 2.6 * smoothstep(3, 12, lakeS);
335	      depth += rough * smoothstep(2, 9, lakeS);
336	      depth += fineNoise * 0.75 * smoothstep(4, 14, lakeS);
337	      return SEA_LEVEL - Math.max(0.6, depth);
338	    }
339	    const out = -lakeS;
340	    const slopeNoise = (fbm2(x * 0.009, z * 0.009, 2, this.seed + 90) - 0.5);
341	    const slope = 0.26 + 0.16 * smoothstep(0, 34, out) + slopeNoise * 0.16;
342	    const bench = Math.min(out, 5) * 0.2;
343	    let h = SEA_LEVEL + bench + Math.max(0, out - 5) * slope;
344	    h += bankNoise * 4.0 * smoothstep(0, 18, out);
345	    h += fineNoise * 0.9 * smoothstep(1, 8, out);
346	    const blend = smoothstep(24, 56, out + bankNoise * 10);
347	    return h * (1 - blend) + base * blend;
348	  }
349	
350	  private biomeAt(x: number, z: number, h: number): number {
351	    const t = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 11);
352	    const m = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 17);
353	    if (h < SEA_LEVEL - 2) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
354	    if (h <= SEA_LEVEL + 1) {
355	      if (h < SEA_LEVEL) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
356	      const shoreNoise = fbm2(x * 0.045, z * 0.045, 2, this.seed + 71);
357	      if (shoreNoise > 0.64) return t < 0.2 ? BIOME.snowy : BIOME.beach;
358	      if (t < 0.2) return BIOME.snowy;
359	      if (t > 0.74 && m < 0.42) return BIOME.desert;
360	      if (t < 0.32) return BIOME.taiga;
361	      if (m > 0.62) return BIOME.forest;
362	      return BIOME.plains;
363	    }
364	    if (h > 108) return BIOME.mountains;
365	    if (t < 0.2) return m > 0.5 ? BIOME.taiga : BIOME.snowy;
366	    if (t < 0.32) return BIOME.taiga;
367	    if (t > 0.74 && m < 0.42) return BIOME.desert;
368	    if (t > 0.66 && m < 0.55) return BIOME.savanna;
369	    if (m > 0.68 && h < SEA_LEVEL + 8 && t > 0.4) return BIOME.swamp;
370	    if (m > 0.62) return BIOME.forest;
371	    if (m > 0.5 && t < 0.62) return BIOME.birch;
372	    return BIOME.plains;
373	  }
374	
375	  private isTreeBiome(biome: number): boolean {
376	    return biome === BIOME.forest || biome === BIOME.birch || biome === BIOME.taiga ||
377	      biome === BIOME.plains || biome === BIOME.savanna || biome === BIOME.swamp;
378	  }
