380	  async generate(progress: (f: number, label: string) => void): Promise<void> {
381	    const total = this.gridSize * this.gridSize;
382	    let done = 0;
383	    for (let cx = this.originCX; cx < this.originCX + this.gridSize; cx++) {
384	      for (let cz = this.originCZ; cz < this.originCZ + this.gridSize; cz++) {
385	        this.generateChunk(cx, cz);
386	        done++;
387	        if (done % 8 === 0) {
388	          progress(0.72 + 0.14 * (done / total), `Generating terrain ${done}/${total}`);
389	          await new Promise(r => setTimeout(r, 0));
390	        }
391	      }
392	    }
393	    progress(0.865, 'Building structures');
394	    await new Promise(r => setTimeout(r, 0));
395	    this.structureSites.push(...generateStructures(this));
396	    progress(0.87, 'Lighting the world');
397	    await new Promise(r => setTimeout(r, 0));
398	    this.computeLighting();
399	    progress(0.93, 'Placing features');
400	  }
