402	  private generateChunk(cx: number, cz: number): void {
403	    const c = this.createChunk(cx, cz);
404	    if (c.generated) return;
405	    c.generated = true;
406	    const baseX = cx * 16, baseZ = cz * 16;
407	    const { blocks, biomes, heights } = c;
408	    const ids = this.ids;
409	    const lake = new Float32Array(256);
410	
411	    // First pass: terrain shape and biome, so slopes can be read by the material pass.
412	    for (let lz = 0; lz < 16; lz++) {
413	      for (let lx = 0; lx < 16; lx++) {
414	        const x = baseX + lx, z = baseZ + lz;
415	        const ci = lz * 16 + lx;
416	        const ls = this.lakeSigned(x, z);
417	        const h = Math.floor(this.terrainHeight(x, z, ls));
418	        lake[ci] = ls;
419	        heights[ci] = h;
420	        biomes[ci] = this.biomeAt(x, z, h);
421	      }
422	    }
423	
424	    // Second pass: blocks and surface materials.
425	    for (let lz = 0; lz < 16; lz++) {
426	      for (let lx = 0; lx < 16; lx++) {
427	        const x = baseX + lx, z = baseZ + lz;
428	        const ci = lz * 16 + lx;
429	        const h = heights[ci];
430	        const biome = biomes[ci];
431	        const ls = lake[ci];
432	        const snowy = biome === BIOME.snowy || biome === BIOME.frozenOcean;
433	        const desert = biome === BIOME.desert;
434	        const beach = biome === BIOME.beach;
435	        const ocean = biome === BIOME.ocean || biome === BIOME.frozenOcean;
436	        const mountain = biome === BIOME.mountains;
437	        const nearLake = ls > -16;
438	
439	        let slope = 0;
440	        if (lx > 0) slope = Math.max(slope, Math.abs(h - heights[ci - 1]));
441	        if (lx < 15) slope = Math.max(slope, Math.abs(h - heights[ci + 1]));
442	        if (lz > 0) slope = Math.max(slope, Math.abs(h - heights[ci - 16]));
443	        if (lz < 15) slope = Math.max(slope, Math.abs(h - heights[ci + 16]));
444	
445	        let top = ids.grass_block;
446	        let filler = ids.dirt;
447	        if (desert) { top = ids.sand; filler = ids.sand; }
448	        else if (beach || ocean) {
449	          top = (h > 48 || h < 40) ? ids.sand : ids.gravel;
450	          filler = ids.sand;
451	          if (nearLake && h < SEA_LEVEL) {
452	            const sed = fbm2(x * 0.055, z * 0.055, 2, this.seed + 93);
453	            if (sed > 0.60) top = ids.gravel;
454	            else if (h < SEA_LEVEL - 4 && sed < 0.28) top = ids.clay;
455	          }
456	        }
457	        else if (snowy) { top = ids.snow_block; filler = ids.dirt; }
458	        else if (mountain) { top = h > 112 ? ids.snow_block : ids.stone; filler = ids.stone; }
459	        else if (biome === BIOME.swamp && h < SEA_LEVEL + 3) { top = ids.grass_block; filler = ids.dirt; }
460	
461	        // Patchy beach tongue above the waterline, with gravel bars.
462	        if (!desert && !snowy && !mountain && nearLake && h >= SEA_LEVEL && h <= SEA_LEVEL + 2) {
463	          const patch = fbm2(x * 0.075, z * 0.075, 2, this.seed + 94);
464	          if (h === SEA_LEVEL || (h === SEA_LEVEL + 1 && patch > 0.66) || (h === SEA_LEVEL + 2 && patch > 0.8)) {
465	            top = patch > 0.74 ? ids.gravel : ids.sand;
466	            filler = ids.sand;
467	          } else {
468	            top = ids.grass_block;
469	            filler = ids.dirt;
470	          }
471	        }
472	        // Occasional rocky outcrops on steeper grass banks.
473	        if (!desert && !snowy && !mountain && h > SEA_LEVEL + 2 && slope >= 1) {
474	          const outcrop = fbm2(x * 0.06, z * 0.06, 2, this.seed + 105);
475	          const roll = hash2i(x, z, this.seed + 106);
476	          if ((slope >= 2 && outcrop > 0.53 && roll < 0.5) || (outcrop > 0.72 && roll < 0.22)) {
477	            top = ids.stone;
478	            filler = ids.stone;
479	          }
480	        }
481	
482	        const maxY = Math.max(h, SEA_LEVEL);
483	        for (let y = WORLD_MIN_Y; y <= maxY; y++) {
484	          if (y < WORLD_MIN_Y + 2 + ((hash3i(x, y, z, this.seed + 5) * 2) | 0)) {
485	            blocks[this.idx(x, y, z)] = ids.bedrock;
486	            continue;
487	          }
488	          if (y <= h) {
489	            let id = ids.stone;
490	            if (y < -8) id = ids.deepslate;
491	            if (y > h - 4) {
492	              if (y === h) id = top;
493	              else id = filler;
494	            }
495	            if (y < h - 4 && y < 0 && y > h - 30) {
496	              const r = hash3i(x, y, z, this.seed + 23);
497	              if (r < 0.012) id = ids.coal_ore;
498	              else if (r < 0.019) id = ids.iron_ore;
499	              else if (r < 0.023) id = ids.copper_ore;
500	              else if (r < 0.0242) id = ids.diamond_ore;
501	            }
502	            if (desert && y > h - 5) id = y === h ? ids.sand : ids.sandstone;
503	            blocks[this.idx(x, y, z)] = id;
504	          } else {
505	            let fluid = ids.water;
506	            if (snowy && y === SEA_LEVEL) fluid = ids.ice;
507	            blocks[this.idx(x, y, z)] = fluid;
508	          }
509	        }
510	        if (snowy && h >= SEA_LEVEL && h < 100) {
511	          const sy = h + 1;
512	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
513	        }
514	        if (mountain && h > 112) {
515	          const sy = h + 1;
516	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
517	        }
518	      }
519	    }
520	
521	    // Boulders before trees so a rock spot is not also used for a trunk.
522	    for (let lz = 1; lz < 15; lz++) {
523	      for (let lx = 1; lx < 15; lx++) {
524	        const ci = lz * 16 + lx;
525	        this.placeBoulders(c, baseX + lx, baseZ + lz, heights[ci], lake[ci], biomes[ci]);
526	      }
527	    }
528	
529	    // Trees. Kept away from chunk borders so canopies stay inside; thinned near the shore.
530	    const treeSpots: [number, number][] = [];
531	    for (let lz = 3; lz < 13; lz++) {
532	      for (let lx = 3; lx < 13; lx++) {
533	        const x = baseX + lx, z = baseZ + lz;
534	        const ci = lz * 16 + lx;
535	        const h = heights[ci];
536	        if (h < SEA_LEVEL) continue;
537	        const biome = biomes[ci];
538	        const ground = this.getBlock(x, h, z);
539	        if (ground !== ids.grass_block) continue;
540	        if (this.getBlock(x, h + 1, z) !== 0) continue;
541	        const rnd = hash2i(x, z, this.seed + 41);
542	        if (!this.isTreeBiome(biome)) continue;
543	        let chance = this.treeChance(biome);
544	        if (lake[ci] > -12) chance *= 0.3;
545	        else if (lake[ci] > -24) chance *= 0.65;
546	        if (rnd >= chance) continue;
547	        if (treeSpots.some(([tx, tz]) => (tx - x) * (tx - x) + (tz - z) * (tz - z) < 12)) continue;
548	        treeSpots.push([x, z]);
549	        this.placeTree(c, x, h + 1, z, biome, hash2i(x, z, this.seed + 43));
550	      }
551	    }
552	
553	    // Cacti and ground cover, across the whole chunk (plants never cross borders).
554	    for (let lz = 0; lz < 16; lz++) {
555	      for (let lx = 0; lx < 16; lx++) {
556	        const x = baseX + lx, z = baseZ + lz;
557	        const ci = lz * 16 + lx;
558	        const h = heights[ci];
559	        const biome = biomes[ci];
560	        if (biome === BIOME.desert) {
561	          if (this.getBlock(x, h, z) === ids.sand && this.getBlock(x, h + 1, z) === 0 &&
562	            hash2i(x, z, this.seed + 47) < 0.018) {
563	            this.placeCactus(c, x, h + 1, z, hash2i(x, z, this.seed + 47));
564	          }
565	        }
566	        this.placeVegetation(c, x, z, h, biome, lake[ci]);
567	      }
568	    }
569	  }
570	
571	  private placeBoulders(c: Chunk, x: number, z: number, h: number, lakeS: number, biome: number): void {
572	    if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.desert ||
573	      biome === BIOME.beach || biome === BIOME.snowy) return;
574	    if (h < SEA_LEVEL + 1 || h > 105) return;
575	    const ids = this.ids;
576	    if (this.getBlock(x, h, z) !== ids.grass_block) return;
577	    if (this.getBlock(x, h + 1, z) !== 0) return;
578	    const chance = lakeS > -24 ? 0.004 : 0.002;
579	    if (hash2i(x, z, this.seed + 111) >= chance) return;
580	    const lx = x & 15, lz = z & 15;
581	    if (lx < 1 || lx > 14 || lz < 1 || lz > 14) return;
582	
583	    const size = 1 + ((hash2i(x, z, this.seed + 112) * 3) | 0); // 1-3 extra blocks
584	    const mossy = hash2i(x, z, this.seed + 113) < 0.4;
585	    const spots: [number, number][] = [[0, 0]];
586	    if (size >= 2) spots.push(hash2i(x, z, this.seed + 114) < 0.5 ? [1, 0] : [0, 1]);
587	    if (size >= 3) spots.push(hash2i(x, z, this.seed + 115) < 0.5 ? [-1, 0] : [0, -1]);
588	    for (let i = 0; i < spots.length; i++) {
589	      const nx = x + spots[i][0], nz = z + spots[i][1];
590	      if (nx < 0 || nz < 0) continue;
591	      const nlx = nx & 15, nlz = nz & 15;
592	      if (nlx < 0 || nlz < 0) continue;
593	      const nh = c.heights[nlz * 16 + nlx];
594	      if (Math.abs(nh - h) > 1) continue;
595	      if (c.blocks[this.idx(nx, nh, nz)] !== ids.grass_block) continue;
596	      if (c.blocks[this.idx(nx, nh + 1, nz)] !== 0) continue;
597	      const block = (i === 0 ? mossy : hash2i(nx, nz, this.seed + 116) < 0.35)
598	        ? ids.mossy_cobblestone : ids.stone;
599	      this.setLocal(c, nx, nh + 1, nz, block, true);
600	      if (i === 0 && size >= 3) this.setLocal(c, nx, nh + 2, nz, block, true);
601	    }
602	  }
603	
604	  private placeVegetation(c: Chunk, x: number, z: number, h: number, biome: number, lakeS: number): void {
605	    if (h < SEA_LEVEL || this.getBlock(x, h + 1, z) !== 0) return;
606	    const ids = this.ids;
607	    const ground = this.getBlock(x, h, z);
608	    if (ground === ids.sand || ground === ids.red_sand) {
609	      const deadChance = biome === BIOME.desert ? 0.006 : (lakeS > -18 ? 0.006 : 0);
610	      if (deadChance > 0 && hash2i(x, z, this.seed + 120) < deadChance) {
611	        this.setIfAir(c, x, h + 1, z, ids.dead_bush);
612	      }
613	      return;
614	    }
615	    if (ground !== ids.grass_block) return;
616	    if (biome === BIOME.snowy || biome === BIOME.frozenOcean || biome === BIOME.desert ||
617	      biome === BIOME.mountains) return;
618	
619	    const patch = fbm2(x * 0.047, z * 0.047, 2, this.seed + 93);
620	    const forest = biome === BIOME.forest || biome === BIOME.birch;
621	    const taiga = biome === BIOME.taiga;
622	    const swamp = biome === BIOME.swamp;
623	    const plains = biome === BIOME.plains || biome === BIOME.beach;
624	    const savanna = biome === BIOME.savanna;
625	
626	    // Compact flower clusters: a deterministic centre per 7x7 cell, one species per cluster.
627	    const cellX = Math.floor(x / 7), cellZ = Math.floor(z / 7);
628	    const clusterChance = forest ? 0.13 : plains ? 0.09 : savanna ? 0.035 : swamp ? 0.02 : taiga ? 0.012 : 0;
629	    if (clusterChance > 0 && hash2i(cellX, cellZ, this.seed + 96) < clusterChance) {
630	      const cx = cellX * 7 + 2 + ((hash2i(cellX, cellZ, this.seed + 97) * 3) | 0);
631	      const cz = cellZ * 7 + 2 + ((hash2i(cellX, cellZ, this.seed + 98) * 3) | 0);
632	      const dx = x - cx, dz = z - cz;
633	      if (dx * dx + dz * dz <= 4 && hash2i(x, z, this.seed + 99) < 0.55) {
634	        const flower = this.flowerIds[(hash2i(cellX, cellZ, this.seed + 100) * this.flowerIds.length) | 0];
635	        this.setIfAir(c, x, h + 1, z, flower);
636	        return;
637	      }
638	    }
639	
640	    let fernChance = 0;
641	    if (forest) fernChance = 0.012 + (patch > 0.5 ? 0.025 : 0);
642	    else if (taiga) fernChance = 0.045;
643	    else if (swamp) fernChance = 0.03;
644	    else if (plains) fernChance = 0.004;
645	    if (fernChance > 0 && hash2i(x, z, this.seed + 121) < fernChance) {
646	      this.setIfAir(c, x, h + 1, z, ids.fern);
647	      return;
648	    }
649	
650	    let grassChance = 0;
651	    if (forest) grassChance = patch > 0.42 ? 0.4 : 0.06;
652	    else if (plains) grassChance = patch > 0.46 ? 0.34 : 0.04;
653	    else if (taiga) grassChance = patch > 0.4 ? 0.26 : 0.05;
654	    else if (savanna) grassChance = patch > 0.5 ? 0.22 : 0.03;
655	    else if (swamp) grassChance = patch > 0.38 ? 0.36 : 0.1;
656	    if (hash2i(x, z, this.seed + 53) < grassChance) {
657	      this.setIfAir(c, x, h + 1, z, ids.short_grass);
658	    }
659	  }
660	
661	  private treeChance(biome: number): number {
662	    if (biome === BIOME.forest) return 0.035;
663	    if (biome === BIOME.birch) return 0.03;
664	    if (biome === BIOME.taiga) return 0.04;
665	    if (biome === BIOME.swamp) return 0.015;
666	    if (biome === BIOME.savanna) return 0.004;
667	    return 0.006;
668	  }
669	
670	  private setLocal(c: Chunk, x: number, y: number, z: number, id: number, overwrite = false): void {
671	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return;
672	    const lx = x & 15, lz = z & 15;
673	    const i = this.idx(x, y, z);
674	    if (!overwrite && c.blocks[i] !== 0) return;
675	    c.blocks[i] = id;
676	  }
677	
678	  private setIfAir(c: Chunk, x: number, y: number, z: number, id: number): void {
679	    this.setLocal(c, x, y, z, id, false);
680	  }
681	
682	  private placeTree(c: Chunk, x: number, y: number, z: number, biome: number, rnd: number): void {
683	    const ids = this.ids;
684	    let log = ids.oak_log, leaves = ids.oak_leaves;
685	    let height = 4;
686	    const spruce = biome === BIOME.taiga;
687	    const birch = biome === BIOME.birch;
688	    if (birch) { log = ids.birch_log; leaves = ids.birch_leaves; height = 5 + ((rnd * 3) | 0); }
689	    else if (spruce) { log = ids.spruce_log; leaves = ids.spruce_leaves; height = 7 + ((rnd * 3) | 0); }
690	    else { height = 4 + ((rnd * 3) | 0); }
691	    if (this.getBlock(x, y + height, z) !== 0) return;
692	    for (let i = 0; i < height; i++) this.setLocal(c, x, y + i, z, log, true);
693	    const top = y + height - 1;
694	
695	    if (spruce) {
696	      // Conical, layered spruce with alternating branch tips and a spire.
697	      for (let ly = top; ly >= y + 2; ly--) {
698	        const d = top - ly;
699	        let r = d <= 1 ? 1 : d <= 4 ? 2 : 3;
700	        if (height < 9) r = Math.min(r, 2);
701	        for (let dx = -r; dx <= r; dx++) {
702	          for (let dz = -r; dz <= r; dz++) {
703	            if (Math.abs(dx) === r && Math.abs(dz) === r) continue;
704	            if (dx === 0 && dz === 0 && ly <= top) continue;
705	            this.setIfAir(c, x + dx, ly, z + dz, leaves);
706	          }
707	        }
708	        if (d >= 1 && d <= 4 && (d & 1) === 1) {
709	          const t = r + 1;
710	          this.setIfAir(c, x + t, ly, z, leaves);
711	          this.setIfAir(c, x - t, ly, z, leaves);
712	          this.setIfAir(c, x, ly, z + t, leaves);
713	          this.setIfAir(c, x, ly, z - t, leaves);
714	        }
715	      }
716	      this.setIfAir(c, x, top + 1, z, leaves);
717	      return;
718	    }
719	
720	    // Oak and birch: two broad 5x5 layers, then two 3x3 layers with a plus-shaped cap.
721	    for (let ly = top - 2; ly <= top + 1; ly++) {
722	      const layer = top + 1 - ly; // 0 = top cap, 3 = lowest 5x5 layer
723	      const r = layer <= 1 ? 1 : 2;
724	      for (let dx = -r; dx <= r; dx++) {
725	        for (let dz = -r; dz <= r; dz++) {
726	          if (dx === 0 && dz === 0 && ly <= top) continue;
727	          const corner = Math.abs(dx) === r && Math.abs(dz) === r;
728	          if (corner) {
729	            const roll = hash3i(x + dx, ly, z + dz, this.seed + 61);
730	            if (r === 2 && roll < (birch ? 0.55 : 0.3)) continue;
731	            if (r === 1 && roll < 0.5) continue;
732	          }
733	          this.setIfAir(c, x + dx, ly, z + dz, leaves);
734	        }
735	      }
736	    }
737	    // Small diagonal lobes on the upper layer widen the crown without making a flat disc.
738	    const lobeChance = birch ? 0.3 : 0.55;
739	    for (const [dx, dz] of [[2, 2], [-2, 2], [2, -2], [-2, -2]]) {
740	      if (hash3i(x + dx, top, z + dz, this.seed + 62) < lobeChance) {
741	        this.setIfAir(c, x + dx, top, z + dz, leaves);
742	      }
743	    }
744	    this.setIfAir(c, x, top + 2, z, leaves);
745	  }
746	
747	  private placeCactus(c: Chunk, x: number, y: number, z: number, rnd: number): void {
748	    const height = 1 + ((rnd * 3) | 0);
