876	  relightAround(x: number, y: number, z: number, radius = 20): void {
877	    const x0 = Math.max(this.minWorldX, x - radius), x1 = Math.min(this.maxWorldX, x + radius);
878	    const z0 = Math.max(this.minWorldZ, z - radius), z1 = Math.min(this.maxWorldZ, z + radius);
879	    const y0 = Math.max(WORLD_MIN_Y, y - radius), y1 = Math.min(WORLD_MAX_Y - 1, y + radius);
880	    // Reset light in the box, then recompute skylight columns and flood from the box boundary and emitters.
881	    for (let zz = z0; zz <= z1; zz++) {
882	      for (let xx = x0; xx <= x1; xx++) {
883	        const c = this.chunkAt(xx >> 4, zz >> 4);
884	        if (!c) continue;
885	        for (let yy = y0; yy <= y1; yy++) {
886	          const i = this.idx(xx, yy, zz);
887	          c.light[i] = 0;
888	        }
889	      }
890	    }
891	    this.skyQueue.clear();
892	    this.blockQueue.clear();
893	    for (let zz = z0; zz <= z1; zz++) {
894	      for (let xx = x0; xx <= x1; xx++) {
895	        let sky = y1 + 1 < WORLD_MAX_Y ? this.getSky(xx, y1 + 1, zz) : 15;
896	        for (let yy = y1; yy >= y0; yy--) {
897	          const c = this.chunkAt(xx >> 4, zz >> 4);
898	          if (!c) break;
899	          const i = this.idx(xx, yy, zz);
900	          const def = this.rocks.get(c.blocks[i]);
901	          if (def.flags && def.flags.opaque) { sky = 0; continue; }
902	          c.light[i] = (sky << 4) | (c.light[i] & 15);
903	          if (def.flags && def.flags.lightOpacity > 0) sky = Math.max(0, sky - def.flags.lightOpacity);
904	          if (sky > 0) this.skyQueue.push(this.pack(xx, yy, zz));
905	        }
906	      }
907	    }
908	    // Boundary seeds from outside the box.
909	    for (let zz = z0; zz <= z1; zz++) {
910	      for (let yy = y0; yy <= y1; yy++) {
911	        for (const xx of [x0 - 1, x1 + 1]) {
912	          if (xx < this.minWorldX || xx > this.maxWorldX) continue;
913	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
914	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
915	        }
916	      }
917	    }
918	    for (let xx = x0; xx <= x1; xx++) {
919	      for (let yy = y0; yy <= y1; yy++) {
920	        for (const zz of [z0 - 1, z1 + 1]) {
921	          if (zz < this.minWorldZ || zz > this.maxWorldZ) continue;
922	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
923	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
924	        }
925	      }
926	    }
927	    for (let zz = z0; zz <= z1; zz++) {
928	      for (let xx = x0; xx <= x1; xx++) {
929	        for (const yy of [y0 - 1, y1 + 1]) {
930	          if (yy < WORLD_MIN_Y || yy >= WORLD_MAX_Y) continue;
931	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
932	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
933	        }
934	      }
935	    }
936	    // Emitters inside the box.
937	    for (let zz = z0; zz <= z1; zz++) {
938	      for (let xx = x0; xx <= x1; xx++) {
939	        const c = this.chunkAt(xx >> 4, zz >> 4);
940	        if (!c) continue;
941	        for (let yy = y0; yy <= y1; yy++) {
942	          const em = this.rocks.emission[c.blocks[this.idx(xx, yy, zz)]];
943	          if (em > 0) {
944	            this.setBlockLight(xx, yy, zz, em);
945	            this.blockQueue.push(this.pack(xx, yy, zz));
946	          }
947	        }
948	      }
949	    }
950	    this.floodSkyBox(x0, x1, y0, y1, z0, z1);
951	    this.floodBlockBox(x0, x1, y0, y1, z0, z1);
952	  }
