1003	  findSpawn(): { x: number, y: number, z: number, yaw: number } {
1004	    const coast = this.findCoastSpawn();
1005	    if (coast) return coast;
1006	    let best: { x: number, y: number, z: number } | null = null;
1007	    let bestScore = -1e9;
1008	    for (let r = 0; r <= 88; r += 4) {
1009	      const steps = r === 0 ? 1 : Math.min(72, Math.max(16, Math.round(r * 1.2)));
1010	      for (let a = 0; a < steps; a++) {
1011	        const ang = (a / steps) * Math.PI * 2;
1012	        const x = Math.round(Math.cos(ang) * r);
1013	        const z = Math.round(Math.sin(ang) * r);
1014	        const c = this.chunkAt(x >> 4, z >> 4);
1015	        if (!c) continue;
1016	        const h = c.heights[(z & 15) * 16 + (x & 15)];
1017	        const biome = this.getBiome(x, z);
1018	        const minH = biome === BIOME.beach ? SEA_LEVEL : SEA_LEVEL + 2;
1019	        if (h < minH || h > 132) continue;
1020	        const top = this.getBlock(x, h, z);
1021	        if (top !== this.ids.grass_block && top !== this.ids.sand) continue;
1022	        if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.mountains) continue;
1023	        let clear = true;
1024	        for (let dy = 1; dy <= 5; dy++) {
1025	          const above = this.getBlock(x, h + dy, z);
1026	          if (above !== 0 && this.rocks.solid[above]) { clear = false; break; }
1027	        }
1028	        if (!clear) continue;
1029	        let trees = 0;
1030	        for (let dz = -4; dz <= 4; dz++) {
1031	          for (let dx = -4; dx <= 4; dx++) {
1032	            for (let dy = 1; dy <= 14; dy++) {
1033	              const id = this.getBlock(x + dx, h + dy, z + dz);
1034	              if (this.isLeaves(id)) trees++;
1035	            }
1036	          }
1037	        }
1038	        if (trees > 24) continue;
1039	        let water = 0;
1040	        for (let k = 0; k < 16; k++) {
1041	          const aa = (k / 16) * Math.PI * 2;
1042	          for (let d = 8; d <= 40; d += 4) {
1043	            if (this.getBlock(Math.round(x + Math.cos(aa) * d), SEA_LEVEL, Math.round(z + Math.sin(aa) * d)) === this.ids.water) water++;
1044	          }
1045	        }
1046	        let open = 0;
1047	        for (let k = 0; k < 8; k++) {
1048	          const aa = (k / 8) * Math.PI * 2;
1049	          const cc = this.chunkAt((x + Math.round(Math.cos(aa) * 24)) >> 4, (z + Math.round(Math.sin(aa) * 24)) >> 4);
1050	          if (!cc) continue;
1051	          const hh = cc.heights[((z + Math.round(Math.sin(aa) * 24)) & 15) * 16 + ((x + Math.round(Math.cos(aa) * 24)) & 15)];
1052	          if (hh < h + 6) open++;
1053	        }
1054	        const biomeScore = biome === BIOME.beach ? 20 : biome === BIOME.plains ? 6.5 : biome === BIOME.savanna ? 4.5 : biome === BIOME.birch ? 1 : 0;
1055	        const score = biomeScore + Math.min(7, water * 0.18) + open * 0.22 - trees * 0.12 - Math.abs(h - 70) * 0.035;
1056	        if (score > bestScore) {
1057	          bestScore = score;
1058	          best = { x, y: h + 1, z };
1059	        }
1060	      }
1061	    }
1062	    if (!best) best = { x: 8, y: 100, z: 8 };
1063	    const yaw = this.suggestYaw(best.x, best.z);
1064	    this.setViewDirection(yaw);
1065	    this.clearViewCorridor(best.x, best.y, best.z, yaw);
1066	    return { ...best, yaw };
1067	  }
1068	
1069	  private heightOfColumn(x: number, z: number): number {
1070	    const c = this.chunkAt(x >> 4, z >> 4);
1071	    if (!c) return 0;
1072	    return c.heights[(z & 15) * 16 + (x & 15)];
1073	  }
