1080	  /**
1081	   * Removes only the trees that intersect the narrow wedge between the spawn
1082	   * eye and the water, leaving the shore vegetation on both sides intact.
1083	   */
1084	  private clearViewCorridor(sx: number, sy: number, sz: number, yaw: number): void {
1085	    const fx = -Math.sin(yaw), fz = Math.cos(yaw);
1086	    const roots = new Map<string, [number, number, number]>();
1087	    for (let d = 2; d <= 14; d++) {
1088	      const cx = sx + fx * d, cz = sz + fz * d;
1089	      for (let o = -2; o <= 2; o++) {
1090	        const x = Math.round(cx - fz * o);
1091	        const z = Math.round(cz + fx * o);
1092	        for (let y = sy - 2; y <= sy + 10; y++) {
1093	          if (!this.isLog(this.getBlock(x, y, z))) continue;
1094	          let by = y;
1095	          while (by > sy - 10 && this.isLog(this.getBlock(x, by - 1, z))) by--;
1096	          roots.set(`${x},${by},${z}`, [x, by, z]);
1097	        }
1098	      }
1099	    }
1100	    for (const [bx, by, bz] of roots.values()) {
1101	      for (let dz = -2; dz <= 2; dz++) {
1102	        for (let dx = -2; dx <= 2; dx++) {
1103	          for (let y = by; y <= by + 10; y++) {
1104	            const id = this.getBlock(bx + dx, y, bz + dz);
1105	            if (this.isTreeBlock(id)) this.setBlock(bx + dx, y, bz + dz, 0);
1106	          }
1107	        }
1108	      }
1109	    }
1110	  }
