1112	  private findCoastSpawn(): { x: number, y: number, z: number, yaw: number } | null {
1113	    const waters: [number, number][] = [];
1114	    for (const c of this.chunks.values()) {
1115	      for (let lz = 0; lz < 16; lz += 3) {
1116	        for (let lx = 0; lx < 16; lx += 3) {
1117	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
1118	          if (this.getBlock(x, SEA_LEVEL, z) === this.ids.water && this.getBlock(x, SEA_LEVEL + 1, z) === 0) {
1119	            waters.push([x, z]);
1120	          }
1121	        }
1122	      }
1123	    }
1124	    if (!waters.length) return null;
1125	    let sumX = 0, sumZ = 0;
1126	    for (const [wx, wz] of waters) { sumX += wx; sumZ += wz; }
1127	    const waterCenterX = sumX / waters.length, waterCenterZ = sumZ / waters.length;
1128	    type Coast = { x: number, z: number, y: number, yaw: number, score: number };
1129	    let best: Coast | null = null;
1130	    for (let wi = 0; wi < waters.length; wi += 5) {
1131	      const [wx, wz] = waters[wi];
1132	      for (let r = 6; r <= 26; r += 2) {
1133	        const steps = Math.max(12, r * 2);
1134	        for (let a = 0; a < steps; a++) {
1135	          const ang = (a / steps) * Math.PI * 2;
1136	          const x = Math.round(wx + Math.cos(ang) * r);
1137	          const z = Math.round(wz + Math.sin(ang) * r);
1138	          if (Math.abs(x) > 90 || Math.abs(z) > 90) continue;
1139	          const c = this.chunkAt(x >> 4, z >> 4);
1140	          if (!c) continue;
1141	          const h = c.heights[(z & 15) * 16 + (x & 15)];
1142	          if (h < SEA_LEVEL || h > SEA_LEVEL + 34) continue;
1143	          const top = this.getBlock(x, h, z);
1144	          if (top !== this.ids.grass_block && top !== this.ids.sand) continue;
1145	          const biome = this.getBiome(x, z);
1146	          if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.mountains) continue;
1147	          let clear = true;
1148	          for (let dy = 1; dy <= 5; dy++) {
1149	            const above = this.getBlock(x, h + dy, z);
1150	            if (above !== 0 && this.rocks.solid[above]) { clear = false; break; }
1151	          }
1152	          if (!clear) continue;
1153	          const toWaterX = waterCenterX - x, toWaterZ = waterCenterZ - z;
1154	          const toWaterLen = Math.hypot(toWaterX, toWaterZ) || 1;
1155	          const fwdX = toWaterX / toWaterLen, fwdZ = toWaterZ / toWaterLen;
1156	          // Require a lenient downhill sight line toward the lake centre.
1157	          let blocked = false;
1158	          for (let t = 3; t <= 18; t += 3) {
1159	            if (this.heightOfColumn(Math.round(x + fwdX * t), Math.round(z + fwdZ * t)) > h + 2) {
